mapper.select:
SELECT 
FROM deployment_server s
WHERE s.id = #{id}
  AND s.deleted = 0
  AND EXISTS (
      SELECT 1
      FROM deployment_server_project dsp
      JOIN project p ON p.id = dsp.project_id
      WHERE dsp.server_id = s.id
        AND (
          p.owner_id = #{ownerId}
          OR EXISTS (
            SELECT 1 FROM project_member pm
            WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
          )
        )
        AND p.deleted = 0
  )

SELECT server_id, project_id FROM deployment_server_project WHERE server_id IN
#{serverId}
ORDER BY server_id, project_id

SELECT COUNT(DISTINCT s.id)
FROM deployment_server s
JOIN deployment_server_project dsp ON dsp.server_id = s.id
WHERE dsp.project_id IN

    #{projectId}

  AND s.name = #{name}
  AND s.deleted = 0

    AND s.id != #{excludingId}

